}

.offline__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* ------------------------------------------------------------------ */
/* Transcript notices and tags                                        */
/* ------------------------------------------------------------------ */
.message--notice {
  display: block;
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(99, 102, 241, 0.055);
  font-size: 0.84rem;
}

.message--notice .markdown p:first-child {
  margin-top: 0;
}

.message--notice .markdown p:last-child {
  margin-bottom: 0;
}

.message__tag {
  display: inline-block;
  margin-bottom: 6px;
  padding: 2px 7px;
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 999px;
  color: #f0b45a;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* A failure shown in place of the thing that failed. */
.failure {
  margin-top: 8px;
