  gap: 16px;
  padding-top: 4px;
}

.setup__meta {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: calc(100% - 44px);
  max-width: 720px;
  margin: 6px auto 0;
  color: var(--faint);
  font-size: 0.7rem;
}

.setup__turns {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.setup__replies {
  display: flex;
  flex-wrap: wrap;
