  font-size: 0.8rem;
  line-height: 1.45;
}

/* ------------------------------------------------------------------ */
/* Bell & Notification Badges                                         */
/* ------------------------------------------------------------------ */

.bell-badge {
  position: absolute;
  top: -2px;
  right: -2px;
  display: grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--accent-strong);
  color: #ffffff;
  font-size: 0.62rem;
  font-weight: 700;
  box-shadow: 0 0 8px rgba(99, 102, 241, 0.6);
  animation: pulse-badge 2s infinite ease-in-out;
}

@keyframes pulse-badge {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 0 6px rgba(99, 102, 241, 0.5);
  }
  50% {
    transform: scale(1.1);
    box-shadow: 0 0 12px rgba(139, 140, 248, 0.8);
  }
